                "significance": "这项研究首次建立了傅里叶特征、NTK特征系统与网络学习偏好之间的理论联系。理论上，它将模糊的'频谱偏差'现象精确化为'NTK特征向量偏差'，并用特征值衰减速度量化学习难度；应用上，提出的多尺度架构在不增加参数量的前提下，使PINNs首次能够处理空间频率高达100的时空依赖问题。更深远的意义在于，这套分析框架为'如何设计神经网络架构以匹配目标函数性质'提供了可操作的数学指导。",
                "method": "核心思路是'看透网络偏好，对症下药调频率'。具体流程：\n\n ① 理论分析：推导NTK的积分算子形式，证明其特征函数满足微分方程，揭示特征值决定收敛速度、特征向量决定学习方向；\n\n ② 关键发现：对于玩具模型（一维输入+两层网络），严格求解出NTK特征函数是正弦/余弦，频率正比于傅里叶特征参数σ，特征值间隔反比于σ；\n\n ③ 数值验证：对一般网络，通过离散化计算NTK特征分解，发现σ=1时主导特征向量是低频，σ=10时变成高频——与玩具模型定性一致；\n\n ④ 架构设计：多尺度傅里叶特征（MFF）架构并联多个不同σ的傅里叶映射（如σ=1, 10），通过线性层融合；时空多尺度（ST-MFF）架构对空间和时间坐标分别映射后点乘，类比傅里叶级数的时空分离形式。",
                "innovation": "① 将'频谱偏差'从经验观察上升为数学定理：网络优先沿NTK大特征值对应的特征向量方向学习，而全连接网络的NTK特征值随频率递减；\n\n ② 首次揭示傅里叶特征的作用机制：参数σ直接控制NTK特征向量的频率，本质上是在'调节网络的学习偏好'而非'增加表达能力'；\n\n ③ 提出'频率匹配'原则：最优σ应使NTK主导特征向量频率与目标函数主频一致，过大导致过拟合、过小导致欠拟合；\n\n ④ 多尺度架构无额外参数：通过冻结随机傅里叶特征（不参与训练），实现计算成本几乎不变的性能飞跃"
