                "achievements": "代表性成功案例：\n\n① **湍流闭合发现**（Zanna & Bolton 2020）：用稀疏贝叶斯方法从大尺度海洋模拟数据中发现可解释的亚网格闭包模型，性能优于黑箱神经网络。\n\n② **Burgers方程线性化**（Gin et al. 2021）：通过自编码器网络自动学习Cole-Hopf变换，将非线性Burgers方程转化为线性热方程。\n\n③ **计算流体加速**（Kochkov et al. 2021）：用深度学习校正2D Kolmogorov流，在粗网格上实现十倍加速且保持精度。\n\n④ **天气预测**（Kurth et al. 2023）：FourCastNet使用自适应傅里叶神经算子实现全球高分辨率天气预报加速。",

