                        "content": "作者制定了严格的纳入标准：(1)使用ML输出流体相关PDE的近似解；(2)比较ML求解器与标准数值方法的速度或计算成本。他们专注于流体相关的PDE——包括对流、Burgers方程、Navier-Stokes方程、Poisson方程等——因为这些PDE受到了最多关注，也是作者的专业领域。\n\n搜索过程分两个阶段。第一阶段，他们编制了所有已知从事ML和PDE工作的作者名单(共258人)，查看每个作者自2016年以来在Google Scholar上的每篇文章标题。第二阶段，他们查找引用两篇关键文章的所有论文。最终，他们从358篇候选文章中筛选出82篇符合标准的文章。\n\n值得注意的是，作者排除了使用PINN方法的文章，因为标准数值方法优于PINN在前向问题上已是公认事实。这个排除本身就很说明问题——最广泛研究的ML方法之一，其实并不比传统方法更快。",
