                        "subtitle": "十个案例研究",
                        "content": "作者使用更先进的数值方法重新实现了基线。对于2D不可压缩Navier-Stokes方程，他们使用了Runge-Kutta间断Galerkin方法；对于1D对流和Burgers方程，同样使用RKDG格式；对于Poisson方程，使用连续Galerkin配置的LU分解。这些都是针对相应PDE的高效或最先进方法。\n\n结果具有戏剧性。在10个案例中：\n- **9/10案例**：更强基线比原文中的弱基线**至少快两个数量级**（例外是文章6）\n- **7/10案例**：更强基线**优于ML求解器**（例外是文章1、6、12）\n- **违规模式**：4/10违反规则1，至少6/10违反规则2（使用低效方法和/或低效实现）\n\n让我们看几个具体例子。**文章1**(Li et al., 941次引用)声称比伪谱方法64×64网格'快1000倍'，但当作者使用间断Galerkin方法7×7网格时，发现ML求解器只快7倍。**文章2**(Lu et al., 911次引用)声称比有限差分方法nx=100'快24倍'，但用间断Galerkin方法nx=13时，ML求解器实际上**慢10倍**。**文章4**(Kochkov et al., 429次引用)是发表在PNAS上的高影响力工作，声称比有限体积方法'快80倍'，但当使用伪谱方法时，只是'略微更慢'(这一结果也被Dresdner等人在TPU上复现)。\n\n最戏剧性的是**文章14**(Hsieh et al., 101次引用)，它声称比多重网格方法'更快'，但当使用LU分解时，ML求解器实际上**慢1000倍**。类似地，**文章15**(Brandstetter et al., 87次引用)声称比WENO和伪谱方法'快得多'，但当使用更高效的WENO和有限体积方法时，ML求解器**慢1000倍**。"
