                        "content": "作者强调善意和不当激励作为对正面结果明显偏好的解释：\n\n**善意的文化**：科学ML的文化是这样的：善意的研究者试图找出ML可能对科学有用的方式。在此过程中，他们往往对报告ML无用的方式不太感兴趣。这是一个自然的人性——我们更愿意分享成功而非失败。\n\n**不当的激励**：但更强大的是结构性激励。ML研究奖励新颖想法和正面实验结果。在其他条件相同的情况下，有弱基线和/或报告偏差的文章更可能被著名出版物接受，反过来更可能被广泛引用。\n\n对负面结果的激励在科学ML中特别强，因为职业晋升(在学术界)和高薪工作(在工业界)取决于ML将成为科学问题有用工具的假设。负面结果可能对那个假设产生怀疑，从而削弱对一个人研究领域的正当性。\n\n这创造了一个恶性循环：使用弱基线和报告偏差的文章获得更多关注和引用→这些做法成为隐性规范→新研究者学习和复制这些做法→问题持续存在并加剧。"
