                "context": "在工程设计中，不确定性量化(UQ)需要数千甚至数百万次模拟来估计关键参数的概率分布。然而，现代储能器件的优化设计涉及大量相互关联的控制变量（温度、浓度、孔隙结构等），它们往往呈现非高斯、偏态分布。传统替代模型要么忽略变量间的物理相关性，要么无法保证生成的样本符合物理规律，导致预测失真。",
                "problem": "核心挑战在于：如何让数据驱动模型既保持物理一致性，又能突破计算瓶颈？Hall团队发现，单纯用神经网络拟合输入输出关系会丢失领域知识，而纯物理模拟又太慢。他们的切入点是先用概率图模型(PGM)刻画变量间的依赖结构，再让神经网络学习这个'物理图'中的关键计算瓶颈——这就是GINN的核心思想：用图指导学习，用学习加速图。"
