                "method": "GINN采用四步 workflow：①数据生成——从贝叶斯网络中采样控制变量，用均质化模型计算少量(如10⁴)高质量样本；②训练——构建7输入4输出的全连接网络，用ReLU激活，将昂贵的闭包解作为隐藏层特征学习，通过MSE损失训练50轮；③测试——在独立测试集验证泛化能力，防止过拟合；④预测——训练好的GINN可在5分钟内生成10⁷样本，用于核密度估计。关键是输入层保持CVs的结构化先验（如温度与浓度的相关性），而非独立节点，确保预测物理合理。",
