// 处理新格式综述论文的模态框内容
function createNewFormatReviewModalContent(paper) {
    // 创建标题选项内容 - 新格式综述论文使用panorama、insight、guide
    const titleOptionsContent = paper.titles ? `
        <div class="info-section">
            <h3>标题创意</h3>
            <div class="title-options-modal">
                <div class="title-option-modal panorama">
                    <div class="title-option-header">
                        <span class="title-option-icon">🌍</span>
                        <span class="title-option-type">全景式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.panorama)}</p>
                </div>
                <div class="title-option-modal insight">
                    <div class="title-option-header">
                        <span class="title-option-icon">💡</span>
                        <span class="title-option-type">洞察式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.insight)}</p>
                </div>
                <div class="title-option-modal guide">
                    <div class="title-option-header">
                        <span class="title-option-icon">🗺️</span>
                        <span class="title-option-type">指南式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.guide)}</p>
                </div>
            </div>
        </div>
    ` : '';

    // 创建开篇引入内容
    const openingContent = paper.opening ? `
        <div class="info-section">
            <h3>开篇引入</h3>
            <div class="content-section">
                <h4>开场钩子</h4>
                <p>${processMarkdown(paper.opening.hook || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>全文预览</h4>
                <p>${processMarkdown(paper.opening.preview || '未提供')}</p>
            </div>
        </div>
    ` : '';

    // 创建综述范围内容（如果有）
    const reviewScopeContent = paper.meta.reviewScope ? `
        <div class="info-section">
            <h3>综述范围</h3>
            <div class="content-section">
                <p>${processMarkdown(paper.meta.reviewScope)}</p>
            </div>
        </div>
    ` : '';

    // 创建主体内容
    let mainContentHTML = '';
    if (paper.mainContent && Array.isArray(paper.mainContent)) {
        mainContentHTML = paper.mainContent.map((chapter, index) => {
            // 创建章节内容
            let chapterHTML = `
                <div class="content-section">
                    <h4>${chapter.chapter || `第${index + 1}章`}</h4>
            `;

            // 添加章节引入（如果有）
            if (chapter.intro) {
                chapterHTML += `
                    <div class="chapter-intro">
                        <p>${processMarkdown(chapter.intro)}</p>
                    </div>
                `;
            }

            // 添加子章节（如果有）
            if (chapter.sections && Array.isArray(chapter.sections)) {
                chapter.sections.forEach(section => {
                    chapterHTML += '<div class="sub-section">';

                    // 添加子章节标题（如果有）
                    if (section.subtitle) {
                        chapterHTML += `<h5>${section.subtitle}</h5>`;
                    }

                    // 添加子章节内容
                    if (section.content) {
                        chapterHTML += `<p>${processMarkdown(section.content)}</p>`;
                    }

                    // 添加核心要点（如果有）
                    if (section.keyPoints && Array.isArray(section.keyPoints)) {
                        chapterHTML += '<ul class="key-points">';
                        section.keyPoints.forEach(point => {
                            chapterHTML += `<li>${processMarkdown(point)}</li>`;
                        });
                        chapterHTML += '</ul>';
                    }

                    chapterHTML += '</div>';
                });
            }

            // 添加过渡语（如果有）
            if (chapter.transition) {
                chapterHTML += `
                    <div class="chapter-transition">
                        <p><em>${processMarkdown(chapter.transition)}</em></p>
                    </div>
                `;
            }

            chapterHTML += '</div>';
            return chapterHTML;
        }).join('');
    }

    // 创建结论内容
    let conclusionHTML = '';
    if (paper.conclusion) {
        conclusionHTML = `
            <div class="info-section">
                <h3>收尾总结</h3>
                <div class="content-section">
                    <h4>综合总结</h4>
                    <p>${processMarkdown(paper.conclusion.synthesis || '未提供')}</p>
                </div>
        `;

        // 添加关键洞察（如果有）
        if (paper.conclusion.insights && Array.isArray(paper.conclusion.insights)) {
            conclusionHTML += `
                <div class="content-section">
                    <h4>关键洞察</h4>
                    <ul class="insights-list">
            `;
            paper.conclusion.insights.forEach(insight => {
                conclusionHTML += `<li>${processMarkdown(insight)}</li>`;
            });
            conclusionHTML += `
                    </ul>
                </div>
            `;
        }

        // 添加未来展望（如果有）
        if (paper.conclusion.outlook) {
            conclusionHTML += `
                <div class="content-section">
                    <h4>未来展望</h4>
                    <p>${processMarkdown(paper.conclusion.outlook)}</p>
                </div>
            `;
        }

        // 添加互动引导（如果有）
        if (paper.conclusion.engagement) {
            conclusionHTML += `
                <div class="content-section">
                    <h4>互动引导</h4>
                    <p>${processMarkdown(paper.conclusion.engagement)}</p>
                </div>
            `;
        }

        conclusionHTML += '</div>';
    }

    return `
        ${titleOptionsContent}
        ${openingContent}

        <div class="info-section">
            <h3>基本信息</h3>
            <div class="info-grid">
                <div class="info-item">
                    <strong>作者</strong>
                    <span>${paper.meta.author}</span>
                </div>
                <div class="info-item">
                    <strong>单位</strong>
                    <span>${paper.meta.unit}</span>
                </div>
                <div class="info-item">
                    <strong>期刊</strong>
                    <span>${paper.meta.venue}</span>
                </div>
                <div class="info-item">
                    <strong>发表时间</strong>
                    <span>${paper.meta.date}</span>
                </div>
                <div class="info-item">
                    <strong>论文类型</strong>
                    <span>综述论文</span>
                </div>
            </div>
        </div>

        ${reviewScopeContent}

        <div class="info-section">
            <h3>主体内容</h3>
            ${mainContentHTML}
        </div>

        ${conclusionHTML}

        <div class="info-section">
            <h3>论文链接</h3>
            <div class="paper-links">
                <a href="${paper.meta.links.paper}" class="paper-link" target="_blank">
                    <span>📄</span> 查看论文详情
                </a>
                <a href="${paper.meta.links.download}" class="paper-link" target="_blank">
                    <span>⬇️</span> 下载PDF全文
                </a>
            </div>
        </div>
    `;
}

function createModalContent(paper) {
    // 检查是否为综述论文（通过tags包含"综述"或meta.type为"review"）
    const isReviewPaper = paper.meta.tags && paper.meta.tags.includes('综述') || paper.meta.type === 'review';

    // 如果是综述论文，使用综述模板
    if (isReviewPaper) {
        return createReviewModalContent(paper);
    }

    // 否则使用普通论文模板
    const content = paper.content;
    const extension = paper.extension;
    const closing = paper.closing;

    // 创建标题选项内容
    const titleOptionsContent = paper.titles ? `
        <div class="info-section">
            <h3>标题创意</h3>
            <div class="title-options-modal">
                <div class="title-option-modal suspense">
                    <div class="title-option-header">
                        <span class="title-option-icon">🎯</span>
                        <span class="title-option-type">悬念式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.suspense)}</p>
                </div>
                <div class="title-option-modal value">
                    <div class="title-option-header">
                        <span class="title-option-icon">💎</span>
                        <span class="title-option-type">价值式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.value)}</p>
                </div>
                <div class="title-option-modal conflict">
                    <div class="title-option-header">
                        <span class="title-option-icon">⚡</span>
                        <span class="title-option-type">冲突式</span>
                    </div>
                    <p class="title-option-text">${processMarkdown(paper.titles.conflict)}</p>
                </div>
            </div>
        </div>
    ` : '';

    // 创建导语内容
    const introContent = paper.intro ? `
        <div class="info-section">
            <h3>📖 导语</h3>
            <div class="intro-modal">
                <p class="intro-text-modal">${processMarkdown(paper.intro)}</p>
            </div>
        </div>
    ` : '';

    return `
        ${titleOptionsContent}
        ${introContent}

        <div class="info-section">
            <h3>基本信息</h3>
            <div class="info-grid">
                <div class="info-item">
                    <strong>作者</strong>
                    <span>${paper.meta.author}</span>
                </div>
                <div class="info-item">
                    <strong>单位</strong>
                    <span>${paper.meta.unit}</span>
                </div>
                <div class="info-item">
                    <strong>期刊</strong>
                    <span>${paper.meta.venue}</span>
                </div>
                <div class="info-item">
                    <strong>发表时间</strong>
                    <span>${paper.meta.date}</span>
                </div>
                <div class="info-item">
                    <strong>论文类型</strong>
                    <span>${{
            'theory': '理论研究',
            'application': '应用研究',
            'review': '综述论文'
        }[paper.meta.type] || '研究论文'}</span>
                </div>
            </div>
        </div>

        <div class="info-section">
            <h3>研究背景</h3>
            <div class="content-section">
                <h4>研究领域</h4>
                <p>${processMarkdown(content.background?.field || '未指定')}</p>
            </div>
            <div class="content-section">
                <h4>研究背景</h4>
                <p>${processMarkdown(content.background?.context || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>核心问题</h4>
                <p>${processMarkdown(content.background?.problem || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>主要贡献</h3>
            <div class="content-section">
                <h4>研究意义</h4>
                <p>${processMarkdown(content.contribution?.significance || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>研究方法</h4>
                <p>${processMarkdown(content.contribution?.method || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>创新点</h4>
                <p>${processMarkdown(content.contribution?.innovation || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>实验验证</h3>
            <div class="content-section">
                <h4>实验结果</h4>
                <p>${processMarkdown(content.validation?.experiments || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>研究结论</h4>
                <p>${processMarkdown(content.validation?.conclusion || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>影响评估</h3>
            <div class="content-section">
                <h4>学术影响</h4>
                <p>${processMarkdown(content.evaluation?.impact || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>局限性</h4>
                <p>${processMarkdown(content.evaluation?.limitations || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>未来展望</h3>
            <div class="content-section">
                <p>${processMarkdown(extension?.future || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>总结讨论</h3>
            <div class="content-section">
                <h4>核心总结</h4>
                <p>${processMarkdown(closing?.summary || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>关键收获</h4>
                <p>${processMarkdown(closing?.takeaways || '未提供')}</p>
            </div>
            <div class="content-section">
                <h4>互动讨论</h4>
                <p>${processMarkdown(closing?.discussion || '未提供')}</p>
            </div>
        </div>

        <div class="info-section">
            <h3>论文链接</h3>
            <div class="paper-links">
                <a href="${paper.meta.links.paper}" class="paper-link" target="_blank">
                    <span>📄</span> 查看论文详情
                </a>
                <a href="${paper.meta.links.download}" class="paper-link" target="_blank">
                    <span>⬇️</span> 下载PDF全文
                </a>
            </div>
        </div>
    `;
}

function closeModal() {
    const modal = document.getElementById('paperModal');
    modal.classList.remove('active');
    document.body.style.overflow = '';
}

// 键盘事件处理
document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        closeModal();
    }
});

// 导出函数供全局使用
window.pinnsResearch = {
    papers: pinnsPapers,
    filteredPapers: filteredPapers,
    applyFilters: applyFilters,
    renderPapers: renderPapers
};